===== EnsureUniqueEmail =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;

/**
 * Rejects a create-owner request whose lower-cased email is already used by an existing owner,
 * responding 409 via {@link DuplicateEmailException}. Runs after {@link NormalizeOwnerEmail} (which
 * lower-cases the request email) and before {@link BuildOwner}, comparing case-insensitively against
 * every stored owner's email. Email is optional: a request with no email skips the check, and stored
 * owners with no email never collide.
 */
public class EnsureUniqueEmail {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateEmailException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return; // email is optional
        }
        String normalized = email.toLowerCase();
        for (Owner existing : ownerRepository.findAll()) {
            String existingEmail = existing.getEmail();
            if (existingEmail != null && existingEmail.toLowerCase().equals(normalized)) {
                throw new DuplicateEmailException(email);
            }
        }
    }
}
===== EnsureUniqueTelephone =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Rejects a create-owner request whose E.164 telephone is already used by an existing owner, responding
 * 409 via {@link DuplicateTelephoneException}. Runs after {@link NormalizeOwnerTelephone} (which
 * guarantees the request telephone is the E.164 form) and before {@link BuildOwner}, comparing against
 * every stored owner's telephone normalized to E.164 the same way. Existing telephones that cannot form
 * a valid E.164 number are skipped rather than blocking the request.
 */
public class EnsureUniqueTelephone {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateTelephoneException {
        String telephone = request.getTelephone();
        for (Owner existing : ownerRepository.findAll()) {
            String existingE164;
            try {
                existingE164 = E164Telephone.normalize(existing.getTelephone());
            }
            catch (InvalidTelephoneException ex) {
                continue;
            }
            if (existingE164.equals(telephone)) {
                throw new DuplicateTelephoneException(telephone);
            }
        }
    }
}
===== EnsureUniqueHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects a create-owner request whose last name and address already belong to an existing owner,
 * responding 409 via {@link DuplicateHouseholdException}. Last name is compared case-insensitively
 * after trimming and collapsing every run of whitespace to a single space; the address is compared
 * using its canonical normalized form (see {@link AddressNormalizer}) so, for example, {@code 12 main
 * st} and {@code 12  Main  Street} match. A request that sets {@code sharesHousehold} true bypasses
 * the check and is allowed through.
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = AddressNormalizer.normalize(request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (normalize(existing.getLastName()).equals(lastName)
                    && AddressNormalizer.normalize(existing.getAddress()).equals(address)) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }

    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
===== NormalizeOwnerEmail =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;

/**
 * Normalizes the optional {@code email} of an owner request. Email is optional: a null or blank
 * value is left untouched (no email). When present it must be a syntactically valid address,
 * otherwise the request is rejected with a 400 via {@link InvalidEmailException}. A valid address is
 * mutated in place (via {@code @Val}) to its lower-cased form, so the stored and returned
 * {@code email} is lower-case. Runs before {@link BuildOwner}/{@code ApplyOwner}.
 */
public class NormalizeOwnerEmail {

    /** A pragmatic single-address check: local part, '@', domain with at least one dot, no spaces. */
    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return; // email is optional
        }
        String trimmed = email.trim();
        if (!EMAIL.matcher(trimmed).matches()) {
            throw new InvalidEmailException(email);
        }
        request.setEmail(trimmed.toLowerCase());
    }
}
