package org.springframework.samples.petclinic.rest.escalation;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;

/**
 * Responds 409 when a create-owner request supplies a telephone whose normalized (digits-only)
 * form is already used by another owner. The body is a {@link ProblemDetail}.
 */
public class DuplicateTelephoneExceptionHandler {

    public void handle(@Parameter DuplicateTelephoneException ex,
            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.CONFLICT,
                "The telephone is already used by another owner");
        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(detail));
    }
}
package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown by {@code EnsureUniqueTelephone} when a create-owner request carries a normalized
 * telephone that is already used by an existing owner. Handled globally by
 * {@link DuplicateTelephoneExceptionHandler}, which responds 409.
 */
public class DuplicateTelephoneException extends Exception {

    private final String telephone;

    public DuplicateTelephoneException(String telephone) {
        super("Telephone is already used by another owner: " + telephone);
        this.telephone = telephone;
    }

    public String getTelephone() {
        return this.telephone;
    }
}
